concepts.code:
-- ids only, NULL-safe, distinct
SELECT id FROM customers
EXCEPT
SELECT customer_id FROM orders;

-- any columns, index-friendly, the usual production choice
SELECT c.id, c.name
FROM customers c
WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);

-- broken if orders.customer_id contains a NULL: returns nothing
SELECT id FROM customers WHERE id NOT IN (SELECT customer_id FROM orders);

exercises.schema:
CREATE TABLE agents (
  id   int PRIMARY KEY,
  name text NOT NULL
);
CREATE TABLE tickets (
  id        int PRIMARY KEY,
  agent_id  int REFERENCES agents (id),
  status    text,
  opened_on date NOT NULL
);

